 const render=()=>{clearTimeout(predictionTimer);const now=Date.now(),games=allGames(),external=data.externalPredictions??[],saved=data.retainedExternalPredictions??[];const deadlines=[nextTaipeiMidnight(now),...games.map(g=>Date.parse(g.startAt)),...external.flatMap(p=>[Date.parse(p.sourceUpdatedAt)+8*3600000,Date.parse(p.observedAt)+8*3600000]),...(data.eloForecasts??[]).flatMap(p=>[Date.parse(p.generatedAt)+72*3600000,Date.parse(p.observedAt)+72*3600000])].filter(t=>Number.isFinite(t)&&t>now);if(deadlines.length)predictionTimer=setTimeout(render,Math.min(...deadlines)-now+100);$('#prediction-list').innerHTML=renderPredictionDisplay({games,external,retainedExternal:saved,eloForecasts:data.eloForecasts??[],retainedEloForecasts:data.retainedEloForecasts??[],archived:[...(data.retainedPredictions??[]),...(data.legacyResearchPredictions??[])],league:ui.league,now},{shortTeam,teamLogo,renderArchive});};
