function opponentAnalysisPanel(code){
 const a=data.opponentAnalysis;
 if(!a||a.status!=='available')return `<section class="content-section"><h2>對手強度 / Opponent strength</h2><div class="notice warning"><div><strong>資料不足，暫不計算</strong><small>${esc(a?.reason??'近 30 天例行賽資料尚未完整取得')}；不以不完整樣本推算戰力。</small></div></div></section>`;
 const row=(a.teams??[]).find(x=>x.team===code);
 if(!row)return '<section class="content-section"><h2>對手強度 / Opponent strength</h2><p>這段期間沒有可確認的比賽。</p></section>';
 const old=!a.observedAt||Date.now()-Date.parse(a.observedAt)>24*3600000;
 const records=row.results??[];
 return `<section class="content-section"><h2>近 30 天對手比較 / Opponent strength</h2><div class="notice ${old?'warning':''}"><div><strong>${esc(a.window?.startDate??'')} ～ ${esc(a.window?.endDate??'')} · ${row.games} 場 · ${row.wins} 勝 ${row.losses} 敗${old?' · 資料可能過期':''}</strong><small>ESPN 近 30 個美國比賽日期、本季例行賽已完賽資料；對手勝率使用同期間戰績，排除對本隊交手，為賽後回顧，並非賽前實力或整季分析。更新時間 ${fmt(a.observedAt)}。</small></div></div><div class="team-stat-grid"><article><span>贏球對手平均勝率 · ${row.winsCovered??0}/${row.wins} 場</span><strong>${Number.isFinite(row.opponentWinPctInWins)?percent(row.opponentWinPctInWins):'—'}</strong></article><article><span>輸球對手平均勝率 · ${row.lossesCovered??0}/${row.losses} 場</span><strong>${Number.isFinite(row.opponentWinPctInLosses)?percent(row.opponentWinPctInLosses):'—'}</strong></article><article><span>所有對手平均勝率 · ${row.opponentsCovered??0}/${row.games} 場</span><strong>${Number.isFinite(row.opponentWinPct)?percent(row.opponentWinPct):'—'}</strong></article><article><span>平均淨勝分</span><strong>${row.games?((row.pointsFor-row.pointsAgainst)/row.games).toFixed(1):'—'}</strong></article></div><div class="table-wrap"><table><thead><tr><th>日期</th><th>對手</th><th>結果</th><th>淨勝分</th><th>對手同期戰績*</th></tr></thead><tbody>${records.slice().reverse().map(r=>`<tr><td>${fmt((a.games??[]).find(g=>g.id===r.gameId)?.date)}</td><td>${teamLogo(r.opponent)} ${esc(shortTeam(r.opponent))}</td><td>${r.win?'勝':'敗'}</td><td>${r.margin>0?'+':''}${esc(r.margin)}</td><td>${Number.isFinite(r.opponentWinPct)?`${r.opponentWins} 勝 ${r.opponentLosses} 敗 · ${percent(r.opponentWinPct)}`:'樣本不足'}</td></tr>`).join('')||'<tr><td colspan="5">沒有可用賽事</td></tr>'}</tbody></table></div><p class="fine-print">* 對手同期戰績排除與本隊的所有交手；缺少其他交手時顯示樣本不足。沒有完整賽季或逐場陣容資料，不能僅以此判斷勝利含金量。<a href="#sources">查看資料來源 →</a></p></section>`;
}
