 $('#main').innerHTML=`<a class="rank-back" href="#rankings/MLB">← 返回 MLB 排行榜</a>`+heading('MLB PLAYER PROFILE',`${provisionalNames[p.name]??'中文譯名待確認'} / ${p.name}`,'MLB 官方球員球季數據 / Official season statistics')+`<section class="profile-hero"><img src="https://img.mlbstatic.com/mlb-photos/image/upload/w_240,h_240,c_fill,g_face/v1/people/${id}/headshot/67/current" alt="${esc(p.name)}" onerror="this.hidden=true"><div><h2>${esc(provisionalNames[p.name]??'中文譯名待確認')} <span class="jersey-number">#${esc(mlbContext(p).number)}</span></h2><p>${esc(p.name)}</p>${mlbContext(p).html}<p>${link(`https://www.mlb.com/player/${id}`,'MLB 官方球員頁面')}</p></div></section><section class="content-section"><h2>${esc(season??'')} 球季數據 / Season statistics</h2><div id="mlb-player-stats" role="status">正在讀取 MLB 官方資料…</div></section>`;
